import { Modal } from 'react-native'
import { PurchaseCreditsScreen } from './PurchaseCreditsScreen'
import { useEffect, useState } from 'react'
import { purchaseCreditsEmitter, PurchaseCreditsEvents } from '@/utils/emitter'
import { colors, useTheme } from '@/theme'
import { usePurchase } from '@/utils/hooks'

export function PurchaseCreditsModal() {
	const [isVisible, setIsVisible] = useState(false)

	useEffect(() => {
		const handleOpenModal = () => {
			setIsVisible(true)
		}
		purchaseCreditsEmitter.on(PurchaseCreditsEvents.OPEN_MODAL, handleOpenModal)
		return () => {
			purchaseCreditsEmitter.off(
				PurchaseCreditsEvents.OPEN_MODAL,
				handleOpenModal
			)
		}
	}, [])
	const { theme } = useTheme()

	const { isPurchasing, purchase } = usePurchase({
		onSuccess: () => {
			setIsVisible(false)
		}
	})

	return (
		<Modal
			visible={isVisible}
			onRequestClose={() => setIsVisible(false)}
			animationType="slide"
			allowSwipeDismissal={!isPurchasing}
			presentationStyle="formSheet"
			statusBarTranslucent
			backdropColor={colors[theme].gray[25]}
		>
			<PurchaseCreditsScreen
				onPurchase={purchase}
				isPurchasing={isPurchasing}
			/>
		</Modal>
	)
}
